def can_chain(dominoes):
    """Return a chain of dominoes where adjacent ends match and the chain
    closes on itself (first start equals last end), or None if impossible."""
    if not dominoes:
        return []
    for i, (a, b) in enumerate(dominoes):
        rest = dominoes[:i] + dominoes[i + 1:]
        for d, e in ((a, b), (b, a)):
            result = _chain(rest, d, e)
            if result is not None:
                return [(d, e)] + result
    return None


def _chain(dominoes, start, current):
    """Build a chain from `dominoes` whose left end is `current`,
    checking that the final right end equals `start`."""
    if not dominoes:
        return [] if current == start else None
    for i, (a, b) in enumerate(dominoes):
        rest = dominoes[:i] + dominoes[i + 1:]
        if a == current:
            result = _chain(rest, start, b)
            if result is not None:
                return [(a, b)] + result
        if b == current:
            result = _chain(rest, start, a)
            if result is not None:
                return [(b, a)] + result
    return None
